create or replace function public.platform_admin_overview() returns jsonb language plpgsql stable security definer set search_path=public,auth as $$
begin
if not public.is_platform_admin() then raise exception 'Acesso restrito ao administrador da plataforma'; end if;
return jsonb_build_object(
'summary',jsonb_build_object('organizations',(select count(*) from public.organizations),'trial',(select count(*) from public.organizations where status='trial'),'paid',(select count(distinct organization_id) from public.saas_subscriptions where status in ('active','past_due') and provider is not null),'active',(select count(*) from public.organizations where status='active'),'mrr',(select coalesce(sum(p.monthly_price),0) from public.saas_subscriptions s join public.saas_plans p on p.code=s.plan_code where s.status in ('active','past_due') and s.provider is not null)),
'organizations',coalesce((select jsonb_agg(jsonb_build_object('id',o.id,'name',o.name,'slug',o.slug,'status',o.status,'plan_code',o.plan_code,'trial_ends_at',o.trial_ends_at,'created_at',o.created_at,'subscription_status',s.status,'current_period_end',s.current_period_end,'provider',s.provider,'monthly_price',case when o.plan_code='internal' then 0 else p.monthly_price end,'customer_stage',case when o.plan_code='internal' then 'internal' when s.provider is not null and s.status in ('active','past_due') then 'paid' when o.status='trial' then 'trial' else 'inactive' end,'users',(select count(*) from public.organization_members m where m.organization_id=o.id and m.status='active'),'properties',(select count(*) from public.properties pr where pr.organization_id=o.id and pr.deleted_at is null)) order by o.created_at desc) from public.organizations o left join lateral(select ss.status,ss.current_period_end,ss.provider from public.saas_subscriptions ss where ss.organization_id=o.id order by ss.created_at desc limit 1)s on true left join public.saas_plans p on p.code=o.plan_code),'[]'::jsonb));
end; $$;
revoke all on function public.platform_admin_overview() from public,anon;
grant execute on function public.platform_admin_overview() to authenticated;